cat .engram/manifest.json | head -20; zcat .engram/chunks/*.jsonl.gz | python3 -c '
import sys,json,collections
c=collections.Counter(); t=[]
for line in sys.stdin:
    line=line.strip()
    if not line: continue
    try: o=json.loads(line)
    except Exception as e: print("parse err",e); continue
    if isinstance(o,dict):
        for k in ("observations","sessions","prompts"):
            if k in o and isinstance(o[k],list):
                c[k]+=len(o[k])
                if k=="observations":
                    for x in o[k]: c["proj:"+str(x.get("project"))]+=1; t.append(x.get("title"))
        if "project" in o and "title" in o: c["proj:"+str(o["project"])]+=1; t.append(o["title"])
print(dict(c)); print("\n".join(str(x) for x in t))'

